import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI 프로토콜 (lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/uri-protocol.md","filePath":"ko-KR/user-guide/uri-protocol.md","lastUpdated":1785993908000}'),d={name:"ko-KR/user-guide/uri-protocol.md"};function c(s,e,l,n,i,p){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="uri-프로토콜-lertaro" tabindex="-1">URI 프로토콜 (lertaro://) <a class="header-anchor" href="#uri-프로토콜-lertaro" aria-label="Permalink to &quot;URI 프로토콜 (lertaro://)&quot;">​</a></h1><p>Lertaro는 <code>lertaro://</code> 링크의 핸들러로 스스로를 등록합니다 — 별도의 설치 단계 없이, 앱이 처음 실행될 때 자동으로 설정됩니다. 이를 통해 링크를 열 수 있는 모든 것(브라우저, 바로가기, 다른 앱, 스크립트)이 단축키를 통해서만이 아니라 Lertaro의 특정 부분으로 바로 이동할 수 있습니다.</p><p>Lertaro가 아직 실행 중이 아니라면, <code>lertaro://</code> 링크를 열면 앱을 시작한 뒤 그 링크를 따라갑니다. 이미 실행 중이라면, 실행 중인 인스턴스가 그 링크를 직접 처리합니다 — 절대 두 번째 사본을 시작하지 않습니다.</p><h2 id="경로" tabindex="-1">경로 <a class="header-anchor" href="#경로" aria-label="Permalink to &quot;경로&quot;">​</a></h2><table tabindex="0"><thead><tr><th>링크</th><th>동작</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>퀵 검색 창을 활성화합니다 — 단축키로 불러오는 것과 동일합니다.</td></tr><tr><td><code>lertaro://search/[keyword]</code></td><td><code>[keyword]</code>가 미리 채워진 상태로 퀵 검색 창을 활성화합니다.</td></tr><tr><td><code>lertaro://fullsearch/[keyword]</code></td><td><code>[keyword]</code>가 미리 채워진 상태로 전체 검색 창을 엽니다.</td></tr><tr><td><code>lertaro://settings/page/[section]</code></td><td>설정을 특정 최상위 섹션으로 엽니다.</td></tr><tr><td><code>lertaro://settings/entry/[index]</code></td><td>설정을 열고 강조 표시된 상태로 특정 설정 항목 하나로 바로 이동합니다.</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>첫 번째는 이미 &quot;report&quot;로 필터링된 퀵 검색 창을 활성화하고, 두 번째는 설정을 외관 페이지에서 바로 엽니다.</p><p><code>[section]</code>은 다음 최상위 사이드바 항목 중 하나와 매칭됩니다: <code>Service</code>, <code>Index</code>, <code>General</code>, <code>Appearance</code>, <code>Hotkeys</code>, <code>Plugins</code>, <code>Favorites</code>, <code>History</code>, <code>QuickPanel</code>, <code>About</code> — 대소문자를 구분하지 않습니다.</p><p><code>[index]</code>는 직접 손으로 입력하도록 만들어진 값이 아닙니다 — 이는 선택한 설정에 대해 <a href="./instant-answers.html">설정 검색</a>이 자체적으로 생성하는 숫자로, 그 결과 중 하나를 선택하면 정확히 그 행으로 왕복할 수 있게 해줍니다. 재시작 사이에 안정적으로 유지되지 않으므로, 특정 숫자가 그대로 유지될 것이라고 가정하지 마세요.</p><h2 id="인식되지-않는-링크" tabindex="-1">인식되지 않는 링크 <a class="header-anchor" href="#인식되지-않는-링크" aria-label="Permalink to &quot;인식되지 않는 링크&quot;">​</a></h2><p>알려진 경로와 일치하지 않는 것(오타, 지원되지 않는 섹션, <code>lertaro://</code> 뒤에 붙은 임의의 문자열)은 조용히 무시됩니다. 어떤 웹사이트나 앱이든 먼저 물어보지 않고 이 프로토콜을 호출할 수 있으므로, 잘못되거나 예상치 못한 링크가 놀라운 일을 해서는 안 됩니다 — 여러분 자신의 문제 해결을 위해 로그에는 남지만, 그 외에는 아무 일도 일어나지 않습니다.</p>`,11)])])}const _=t(d,[["render",c]]);export{u as __pageData,_ as default};
